import unittest
from ranges import merge_intervals

class TestMerge(unittest.TestCase):
    def test_overlap(self):
        self.assertEqual(merge_intervals([(1, 4), (2, 6)]), [(1, 6)])

    def test_touching(self):
        self.assertEqual(merge_intervals([(1, 3), (3, 5)]), [(1, 5)])

    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_unsorted(self):
        self.assertEqual(merge_intervals([(5, 7), (1, 3), (2, 4)]), [(1, 4), (5, 7)])

    def test_unsorted_touching(self):
        self.assertEqual(merge_intervals([(3, 5), (1, 3)]), [(1, 5)])

    def test_nested(self):
        self.assertEqual(merge_intervals([(1, 10), (2, 5)]), [(1, 10)])

    def test_disjoint(self):
        self.assertEqual(merge_intervals([(1, 2), (4, 5)]), [(1, 2), (4, 5)])

if __name__ == "__main__":
    unittest.main()
